local BattleEndTrainField = Class('BattleEndTrainField')

------------ LifeCycle ------------
function BattleEndTrainField:__init()
end

function BattleEndTrainField:__delete()
    self.listDataNode = nil
    self.coShowInfoNodes = nil
end

function BattleEndTrainField:Awake()
    self.listDataNode = {}
end

function BattleEndTrainField:Start()
end

function BattleEndTrainField:OnDestroy()
    if self.coShowInfoNodes then
        cs_coroutine.stop(self.coShowInfoNodes)
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
