------------ LifeCycle ------------

function BattleEndTrainField:SetPanel()
    local questId = UIBattlingDataMgr.questId
    local questVo = QuestConfMgr:GetQuestVoById(checkNumber(questId))
    local group = checkNumber(questVo.group)
    local dataType = UIBattleTrainFieldMgr.BATTLE_DATA_TYPE[group]
    for i = 1, #dataType do
        local nodeInfo = KTool.Instantiate(self.RootNodeFather.gameObject, self.TextNode.gameObject)
        if not IsNull(nodeInfo) then
            nodeInfo.name = "TextNode" .. checkString(i)
            KTool.SetActive(nodeInfo, true)
            local lbNode = KTool.GetComponent(nodeInfo, typeof(LuaBehaviour))
            if not IsNull(lbNode) then
                lbNode:Init()
                local ltNode = lbNode.Env
                ltNode:InitNode(checkNumber(dataType[i]), checkNumber(UIBattleTrainFieldMgr:GetDataValueByDataType(dataType[i])))
                table.insert(self.listDataNode, ltNode)
            end
        end
    end
    self:ShowShowInfoNodes()
end

function BattleEndTrainField:ShowShowInfoNodes()
    self.coShowInfoNodes = cs_coroutine.start(function()
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.5))
        for i, node in ipairs(self.listDataNode) do
            node:ShowNode()
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.1))
        end
        self.coShowInfoNodes = nil
    end)
end

return BattleEndTrainField